public static int binarySearch(int[] arr, int target) {
    int left = 0;
    int right = arr.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2; // Find the middle of the portion

        if (arr[mid] == target) return mid; // Found it!

        if (arr[mid] < target) {
            left = mid + 1; // Target is bigger, search the right portion
        } else {
            right = mid - 1; // Target is smaller, search the left portion
        }
    }
    return -1; // Not found
}

public static void bubbleSort(int[] arr) {
    int n = arr.length;

    for (int i = 0; i < n - 1; i++) {
        // Compare adjacent elements
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // THE SWAP PROTOCOL
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

public static void insertionSort(int[] arr) {
    // Start at index 1 (assume index 0 is already sorted)
    for (int i = 1; i < arr.length; i++) {
        int unsortedCard = arr[i]; 
        int j = i - 1;

        // Shift all greater cards to the right to make room
        while (j >= 0 && arr[j] > unsortedCard) {
            arr[j + 1] = arr[j];
            j--;
        }
        // Put the unsorted card in its exact suitable place
        arr[j + 1] = unsortedCard;
    }
}

import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] rawData = {50, 10, 30};

        // 1. Arrays.toString(): Instantly prints the array cleanly [50, 10, 30]
        // (If you try to print an array directly, you just get a garbage memory address!)
        System.out.println(Arrays.toString(rawData));

        // 2. Arrays.equals(): Safely checks if two arrays hold the exact same numbers
        int[] clone = {50, 10, 30};
        System.out.println(Arrays.equals(rawData, clone)); // TRUE

        // 3. Arrays.fill(): Instantly overwrites the entire array with one value
        Arrays.fill(rawData, 999); // array is now {999, 999, 999}
    }
}

