public static void reverseInPlace(int[] arr) {
    int left = 0;
    int right = arr.length - 1;

    // The Two-Pointer Engine
    while (left < right) {
        // 1. Swap the front and back elements
        int temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        // 2. Move the pointers inward
        left++;
        right--;
    }
}

